import os
import numpy as np
import pandas as pd
import warnings
from sklearn.preprocessing import MinMaxScaler
from sklearn.linear_model import LogisticRegression
from sklearn.multiclass import OneVsRestClassifier
from sklearn.pipeline import Pipeline
from sklearn.model_selection import train_test_split
from sklearn.metrics import roc_auc_score

warnings.filterwarnings("ignore")


def load_fold_map():
    """Load train/test split from CVfolds_2.txt"""
    fold_map = {}
    try:
        for path in [
            "./input/essential_data/CVfolds_2.txt",
            "./input/CVfolds_2.txt",
            "essential_data/CVfolds_2.txt",
        ]:
            if os.path.exists(path):
                with open(path, "r") as f:
                    for line in f:
                        parts = line.strip().split(",")
                        if len(parts) >= 2:
                            try:
                                rec_id = int(parts[0].strip())
                                fold = int(parts[1].strip())
                                if fold == 0:
                                    fold_map[rec_id] = "train"
                                elif fold == 1:
                                    fold_map[rec_id] = "test"
                            except (ValueError, TypeError):
                                continue
                return fold_map
    except Exception:
        pass
    return {}


def load_histogram_features():
    """Load histogram of segments features (100-dim)"""
    features_dict = {}
    try:
        for path in [
            "./input/supplemental_data/histogram_of_segments.txt",
            "./input/histogram_of_segments.txt",
            "supplemental_data/histogram_of_segments.txt",
        ]:
            if os.path.exists(path):
                with open(path, "r") as f:
                    lines = f.readlines()
                for line in lines:
                    parts = line.strip().split(",")
                    if len(parts) < 3:
                        continue
                    try:
                        rec_id = int(parts[0].strip())
                        feat_str = parts[1:]
                        if len(feat_str) == 100:
                            feat_vec = np.clip(
                                np.array(
                                    [float(x) for x in feat_str], dtype=np.float64
                                ),
                                0,
                                1,
                            )
                            features_dict[rec_id] = feat_vec
                    except (ValueError, IndexError):
                        continue
                return features_dict
    except Exception:
        pass
    return {}


def load_labels_from_file():
    """Load training labels from rec_labels_test_hidden.txt"""
    train_labels = {}
    try:
        for path in [
            "./input/essential_data/rec_labels_test_hidden.txt",
            "./input/rec_labels_test_hidden.txt",
            "essential_data/rec_labels_test_hidden.txt",
        ]:
            if os.path.exists(path):
                with open(path, "r") as f:
                    for line in f:
                        parts = line.strip().split(",")
                        if len(parts) >= 2:
                            try:
                                rec_id = int(parts[0].strip())
                                label_strs = [p.strip() for p in parts[1:]]
                                labels = []
                                for l in label_strs:
                                    if l != "?":
                                        try:
                                            labels.append(int(l))
                                        except ValueError:
                                            continue
                                if labels:
                                    train_labels[rec_id] = labels
                            except (ValueError, IndexError):
                                continue
                return train_labels
    except Exception:
        pass
    return {}


def main():
    print("=" * 50)
    print("Loading required data files...")
    print("=" * 50)

    num_classes = 19
    train_ids = []
    test_ids = []

    # Load and process fold map
    fold_map = load_fold_map()
    for rid, fold in fold_map.items():
        if fold == "train":
            train_ids.append(int(rid))
        elif fold == "test":
            test_ids.append(int(rid))

    if len(train_ids) == 0 or len(test_ids) == 0:
        raise ValueError("No valid train/test split found!")

    # Load features
    hist_features = load_histogram_features()
    print(f"Loaded histogram features for {len(hist_features)} recordings")

    # Load labels
    train_labels = load_labels_from_file()
    print(f"Loaded training labels for {len(train_labels)} recordings")

    # Filter to training IDs only and prepare features matrix
    train_X_list = []
    train_y_matrix = []

    for rid in train_ids:
        if rid in hist_features and rid in train_labels:
            X = hist_features[rid]
            y_idx = (
                train_X_list.index(X)
                if X in [hist_features[k] for k in train_ids]
                else len(train_X_list)
            )
            train_X_list.append(X)
            train_y_matrix.append(np.zeros(num_classes, dtype=int))
            for label in train_labels[rid]:
                if 0 <= label < num_classes:
                    train_y_matrix[-1][int(label)] = 1

    # Convert to numpy arrays
    X_train_full = np.array(train_X_list, dtype=np.float64)
    y_train_full = np.array(train_y_matrix, dtype=float)

    print(f"Training samples: {len(y_train_full)}")

    # Calculate class weights for balanced learning
    class_counts = np.sum(y_train_full, axis=0)
    mean_count = np.mean(class_counts)
    class_weights = mean_count / class_counts

    # Split into train and validation
    X_train, X_val, y_train, y_val = train_test_split(
        X_train_full, y_train_full, test_size=0.2, random_state=42, stratify=None
    )

    print(f"Train size: {len(y_train)}, Val size: {len(y_val)}")

    # Create proper sklearn Pipeline with MinMaxScaler fitted only on training data
    pipeline = Pipeline(
        [
            ("scaler", MinMaxScaler()),
            (
                "clf",
                OneVsRestClassifier(
                    LogisticRegression(
                        max_iter=1000,
                        C=0.5,
                        solver="lbfgs",
                        random_state=42,
                        class_weight=dict(zip(range(num_classes), class_weights)),
                    )
                ),
            ),
        ]
    )

    # Fit pipeline on training data only (prevents data leakage)
    print("Fitting pipeline on training data...")
    pipeline.fit(X_train, y_train)

    # Evaluate on validation set (no refitting)
    print("Evaluating on validation set...")
    val_pred_proba = pipeline.predict_proba(X_val)

    def safe_auc(y_true, y_pred_proba, n_classes=19):
        auc_scores = []
        for c in range(n_classes):
            yt = y_true[:, c]
            yp = y_pred_proba[:, c]
            if np.all(yt == 0) or np.all(yt == 1) or len(np.unique(yt)) < 2:
                continue
            try:
                au = roc_auc_score(yt, yp)
                auc_scores.append(au)
            except Exception:
                auc_scores.append(0.5)
        return float(np.mean(auc_scores)) if auc_scores else 0.5

    val_auc = safe_auc(y_val, val_pred_proba)
    print(f"Validation AUC: {val_auc:.4f}")

    # Generate predictions for test set
    print("Generating test predictions...")
    test_X_list = [hist_features[rid] for rid in test_ids if rid in hist_features]
    test_X_array = np.array(test_X_list, dtype=np.float64)
    test_pred_proba = pipeline.predict_proba(test_X_array)

    # Create submission file in correct format
    print("Creating submission file...")
    os.makedirs("./submission", exist_ok=True)

    with open("./submission/submission.csv", "w") as f:
        f.write("Id,Probability\n")
        for idx, rid in enumerate(test_ids):
            proba = test_pred_proba[idx][:num_classes]
            for sp_idx, prob in enumerate(proba):
                sub_id = rid * 100 + sp_idx
                f.write(f"{sub_id},{prob:.6f}\n")

